insert into sector_profiles (settore, version, status, pack, changelog)
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Cosa si fa nella prima visita?', $qvh94gw$["come funziona la prima visita","cosa succede alla prima visita","che cosa comprende la prima visita","cosa si fa alla prima visita"]$qvh94gw$::jsonb, 'In genere la prima visita comprende alcune domande sulla sua salute e sulle sue abitudini, un controllo di denti e gengive e, se il dentista lo ritiene utile, delle radiografie. Alla fine il dentista le illustra il percorso di cura consigliato.', $qy417vb${}$qy417vb$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Quanto dura una seduta di igiene dentale?', $q3qkx5x$["quanto dura l igiene","quanto dura la pulizia dei denti","quanto tempo ci vuole per l igiene","quanto dura la pulizia"]$q3qkx5x$::jsonb, 'Una seduta di igiene dentale dura in genere tra i 30 e i 60 minuti; il tempo esatto dipende dalla situazione di ciascuno.', $qbh3ks8${}$qbh3ks8$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Ogni quanto si fa l''igiene dentale?', $qxxuwyy$["ogni quanto si fa la pulizia dei denti","ogni quanto devo fare l igiene","quante volte l anno si fa l igiene","ogni quanto va fatta la pulizia"]$qxxuwyy$::jsonb, 'Di solito si consiglia l''igiene professionale una o due volte l''anno, ma è il dentista a indicare la frequenza più adatta a ciascuna persona.', $qybjc33${}$qybjc33$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Ogni quanto è bene fare un controllo dal dentista?', $q6ext7a$["ogni quanto devo fare il controllo dal dentista","ogni quanto va fatta la visita di controllo","ogni quanto si va dal dentista","ogni quanto controllo"]$q6ext7a$::jsonb, 'In genere è consigliato un controllo ogni sei mesi o una volta l''anno; il dentista può indicare una frequenza diversa in base alle esigenze.', $qlajoce${}$qlajoce$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Lo sbiancamento fa male?', $qqmgwfe$["lo sbiancamento e doloroso","fa male sbiancare i denti","lo sbiancamento da fastidio","lo sbiancamento rovina i denti"]$qqmgwfe$::jsonb, 'Lo sbiancamento può causare una sensibilità temporanea dei denti. Il dentista valuta in visita se è adatto al suo caso e come eseguirlo.', $qxc4clt${}$qxc4clt$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Come funziona lo sbiancamento dentale?', $qorlzgu$["come si fa lo sbiancamento","come funziona lo sbiancamento","in cosa consiste lo sbiancamento","quanto dura lo sbiancamento"]$qorlzgu$::jsonb, 'Lo sbiancamento schiarisce il colore dei denti con prodotti specifici applicati dal dentista o usati a casa sotto il suo controllo. Il risultato e i tempi dipendono dal singolo caso, per questo serve una visita di valutazione.', $q98jdpb${}$q98jdpb$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Quanto dura l''effetto dello sbiancamento?', $qb3gkuo$["quanto dura lo sbiancamento nel tempo","per quanto tempo restano bianchi i denti","l effetto dello sbiancamento e permanente"]$qb3gkuo$::jsonb, 'La durata dell''effetto dipende dal caso e dalle abitudini (per esempio fumo, caffè, tè); il dentista può indicare cosa aspettarsi.', $q4r7ehq${}$q4r7ehq$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Cos''è la devitalizzazione?', $qhfabqm$["cosa e la devitalizzazione","in cosa consiste la devitalizzazione","cosa significa devitalizzare un dente","cos e la cura canalare","come funziona la devitalizzazione"]$qhfabqm$::jsonb, 'La devitalizzazione, o terapia canalare, tratta l''interno del dente (il nervo e i canali) quando è infiammato o infetto, per poter conservare il dente. Serve una visita per capire se è necessaria.', $qe6t5ii${}$qe6t5ii$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Cos''è un impianto dentale?', $q77px9w$["cosa e un impianto dentale","come funziona un impianto","in cosa consiste l impianto","come si fa un impianto","cos e l implantologia"]$q77px9w$::jsonb, 'L''impianto è una radice artificiale, in genere di titanio, inserita nell''osso: su di essa si fissa il nuovo dente. Tempi e modalità vengono definiti dal dentista dopo la visita.', $qfj64ll${}$qfj64ll$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'L''impianto dentale fa male?', $qjycfl7$["fa male l impianto","l impianto e doloroso","si sente dolore con l impianto","si sente male durante l impianto"]$qjycfl7$::jsonb, 'L''intervento viene eseguito con anestesia locale. Per decorso e indicazioni successive il dentista dà istruzioni specifiche per il suo caso.', $qzttle4${}$qzttle4$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Cos''è una corona o capsula dentale?', $qtdobk8$["cosa e una corona dentale","cosa e una capsula","a cosa serve la corona","cos e la capsula","cos e una corona"]$qtdobk8$::jsonb, 'La corona (o capsula) è un rivestimento che ricopre un dente danneggiato per proteggerlo e ripristinarne forma e funzione.', $qts0d6p${}$qts0d6p$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Si usa l''anestesia?', $qzfu9xk$["serve l anestesia","fanno l anestesia","si sente male con l anestesia","mi fate l anestesia","si usa l anestesia"]$qzfu9xk$::jsonb, 'Quando una cura può dare fastidio il dentista utilizza l''anestesia locale e ne parla prima con il paziente.', $qy86shw${}$qy86shw$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Ho paura del dentista, cosa posso fare?', $qtkr0qy$["ho paura del dentista","ho il terrore del dentista","sono molto ansioso per il dentista","ho l ansia del dentista","mi spaventa il dentista"]$qtkr0qy$::jsonb, 'È molto comune: chi lavora in uno studio dentistico è abituato ad accogliere chi ha timore. Può dirlo al momento dell''appuntamento, così il dentista procede con i tempi giusti per lei.', $qrj0wsc${}$qrj0wsc$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Da che età si porta un bambino dal dentista?', $q6mwins$["da che eta si porta il bambino dal dentista","quando portare mio figlio dal dentista","a che eta la prima visita del bambino","da quando si va dal dentista da piccoli"]$q6mwins$::jsonb, 'In generale si consiglia una prima visita intorno ai 3-4 anni, o prima se ci sono dubbi o disturbi. Per i dettagli sui bambini è meglio confrontarsi con lo studio.', $qvinf5s${}$qvinf5s$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_documenti', 'Cosa devo portare alla prima visita?', $qa8xvsq$["cosa devo portare alla visita","che documenti servono per la prima visita","cosa serve portare","devo portare qualcosa alla prima visita"]$qa8xvsq$::jsonb, 'Alla prima visita è utile portare un documento di identità, la tessera sanitaria, eventuali radiografie o referti precedenti e l''elenco dei farmaci che assume. Per altre indicazioni verifichi con lo studio.', $q9hqe3r${}$q9hqe3r$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Servono le radiografie?', $q69z7js$["devo fare le radiografie","fate le radiografie","serve la radiografia","ci vuole la radiografia"]$q69z7js$::jsonb, 'La radiografia viene eseguita solo se il dentista la ritiene necessaria per la valutazione.', $q360g5e${}$q360g5e$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'I denti del giudizio vanno sempre tolti?', $qnveqje$["vanno tolti i denti del giudizio","devo togliere il dente del giudizio","i denti del giudizio vanno estratti"]$qnveqje$::jsonb, 'Non sempre: è il dentista a valutare se estrarli, di solito con una radiografia e una visita.', $qhen0j2${}$qhen0j2$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Quanto dura un trattamento ortodontico?', $qo5fbk4$["quanto dura l apparecchio","quanto tempo si porta l apparecchio","quanto dura la cura ortodontica","per quanto tempo si porta l apparecchio"]$qo5fbk4$::jsonb, 'La durata varia molto da caso a caso, spesso da alcuni mesi a un paio d''anni. Il piano viene definito dal dentista dopo la visita.', $qzb6hyd${}$qzb6hyd$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Cosa sono gli allineatori trasparenti?', $qv8zx5h$["cosa sono gli aligner","cos e invisalign","come funzionano le mascherine trasparenti","cosa sono gli allineatori","l apparecchio trasparente funziona"]$qv8zx5h$::jsonb, 'Gli allineatori trasparenti sono mascherine rimovibili che spostano gradualmente i denti: in alcuni casi sono un''alternativa all''apparecchio fisso. La valutazione spetta al dentista.', $qch9gzy${}$qch9gzy$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Posso andare dal dentista in gravidanza?', $qgyvabm$["si puo andare dal dentista in gravidanza","sono incinta posso fare l igiene","sono in gravidanza posso curarmi i denti","dentista in gravidanza"]$qgyvabm$::jsonb, 'In gravidanza è importante avvisare lo studio: il dentista valuta quali cure sono adatte e in quale momento.', $q7aarmi${}$q7aarmi$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Cosa causa l''alito cattivo?', $qd0d68q$["perche ho l alito cattivo","cosa fare per l alitosi","da cosa dipende l alitosi","come si cura l alitosi"]$qd0d68q$::jsonb, 'L''alito pesante può avere cause diverse: serve una visita per capire da dove dipende, e il dentista indica come intervenire.', $qv05v9m${}$qv05v9m$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Cos''è l''otturazione?', $q5xbm5i$["cosa e l otturazione","come si fa un otturazione","in cosa consiste l otturazione","come funziona l otturazione"]$q5xbm5i$::jsonb, 'L''otturazione serve a ricostruire la parte di dente rovinata, per esempio da una carie, dopo averla pulita. Il dentista stabilisce in visita il tipo di intervento.', $qyc0miu${}$qyc0miu$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Dopo un''estrazione o un intervento cosa devo fare?', $qhi0883$["cosa devo fare dopo l estrazione","cosa fare dopo l intervento","dopo l estrazione cosa si fa","indicazioni dopo un intervento dentale"]$qhi0883$::jsonb, 'Dopo un intervento il dentista dà indicazioni specifiche per il suo caso: le segua con attenzione. Per sintomi particolari contatti direttamente lo studio.', $q2rle3n${}$q2rle3n$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Cos''è l''igiene dentale professionale?', $qd0yt54$["cosa e l igiene dentale","a cosa serve l igiene dentale","cosa si fa nell igiene","in cosa consiste la pulizia dei denti","a cosa serve la pulizia dei denti"]$qd0yt54$::jsonb, 'L''igiene professionale rimuove placca e tartaro che lo spazzolino non elimina e lucida i denti: aiuta a mantenere sane gengive e denti.', $q4fc8dh${}$q4fc8dh$::jsonb);
